CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', university text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', promo_code text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(full_name, university, phone) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid()); CREATE POLICY profile_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,promo_code) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),CASE WHEN coalesce(NEW.raw_user_meta_data->>'promo_code','') ~ '^[A-Za-z0-9]{6}[0-9]{2}$' THEN upper(NEW.raw_user_meta_data->>'promo_code') ELSE '' END); RETURN NEW; END $$;
CREATE TRIGGER evdash_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'inactive' CHECK(status IN('inactive','active','cancelled','past_due')), amount numeric NOT NULL DEFAULT 8 CHECK(amount>=0), current_end timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role; ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY own_subscription ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX subscription_user ON public.subscriptions(user_id);
CREATE FUNCTION public.has_premium() RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.subscriptions WHERE user_id=auth.uid() AND status IN('active','cancelled') AND current_end>now()) $$; REVOKE ALL ON FUNCTION public.has_premium() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_premium() TO authenticated;
CREATE TABLE public.preferences (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, district text NOT NULL DEFAULT '', max_budget integer NOT NULL DEFAULT 800 CHECK(max_budget BETWEEN 100 AND 5000), amenities text[] NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE ON public.preferences TO authenticated; GRANT ALL ON public.preferences TO service_role; ALTER TABLE public.preferences ENABLE ROW LEVEL SECURITY; CREATE POLICY preference_read ON public.preferences FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY preference_create ON public.preferences FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_premium()); CREATE POLICY preference_edit ON public.preferences FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.has_premium()) WITH CHECK(user_id=auth.uid() AND public.has_premium());
CREATE TABLE public.rentals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, home_id text NOT NULL, title text NOT NULL, monthly_amount numeric NOT NULL CHECK(monthly_amount>=0), starts_on date, ends_on date, status text NOT NULL DEFAULT 'active'); GRANT SELECT ON public.rentals TO authenticated; GRANT ALL ON public.rentals TO service_role; ALTER TABLE public.rentals ENABLE ROW LEVEL SECURITY; CREATE POLICY own_rental ON public.rentals FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX rental_user ON public.rentals(user_id);
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, description text NOT NULL, amount numeric NOT NULL CHECK(amount>=0), status text NOT NULL CHECK(status IN('hold','pending','paid','failed','refunded')), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.payments TO authenticated; GRANT ALL ON public.payments TO service_role; ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY; CREATE POLICY own_payment ON public.payments FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE INDEX payment_user ON public.payments(user_id);
CREATE TABLE public.listing_contacts (home_id text PRIMARY KEY, landlord_id uuid REFERENCES public.profiles(id)); GRANT SELECT ON public.listing_contacts TO authenticated; GRANT ALL ON public.listing_contacts TO service_role; ALTER TABLE public.listing_contacts ENABLE ROW LEVEL SECURITY; CREATE POLICY contacts_read ON public.listing_contacts FOR SELECT TO authenticated USING(true);
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, home_id text NOT NULL, landlord_id uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,home_id)); GRANT SELECT ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role; ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY; CREATE POLICY participant_conversation ON public.conversations FOR SELECT TO authenticated USING(auth.uid() IN(user_id,landlord_id)); CREATE INDEX conversation_landlord ON public.conversations(landlord_id);
CREATE FUNCTION public.open_conversation(p_home text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(p_home)>100 OR p_home !~ '^[a-z0-9-]+$' THEN RAISE EXCEPTION 'Invalid listing'; END IF; INSERT INTO public.conversations(user_id,home_id,landlord_id) VALUES(auth.uid(),p_home,(SELECT landlord_id FROM public.listing_contacts WHERE home_id=p_home)) ON CONFLICT(user_id,home_id) DO NOTHING; SELECT id INTO result FROM public.conversations WHERE user_id=auth.uid() AND home_id=p_home; RETURN result; END $$; REVOKE ALL ON FUNCTION public.open_conversation(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.open_conversation(text) TO authenticated;
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role; ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY; CREATE POLICY participant_messages ON public.messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND auth.uid() IN(c.user_id,c.landlord_id))); CREATE POLICY send_message ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND auth.uid() IN(c.user_id,c.landlord_id))); CREATE INDEX message_conversation ON public.messages(conversation_id);
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.notifications TO authenticated; GRANT UPDATE(is_read) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notification_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY notification_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX notification_user ON public.notifications(user_id);
CREATE FUNCTION public.message_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; BEGIN SELECT CASE WHEN NEW.sender_id=c.user_id THEN c.landlord_id ELSE c.user_id END INTO recipient FROM public.conversations c WHERE c.id=NEW.conversation_id; IF recipient IS NOT NULL THEN INSERT INTO public.notifications(user_id,title) VALUES(recipient,'Yeni mesajınız var'); END IF; RETURN NEW; END $$; CREATE TRIGGER new_message_notification AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.message_notification();
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages;
ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;